                           String targetMeta, byte[] itemNbt) {
        try {
            if (itemNbt == null || itemNbt.length == 0) {
                return tryGiveOrDrop(worldId, x, y, z, itemId, amount, targetMeta);
            }
            ServerLevel level = level(worldId);
            if (level == null) return false;
            Identifier itemRl = Identifier.tryParse(itemId);
            if (itemRl == null) return false;
            Item requestedItem = BuiltInRegistries.ITEM.getValue(itemRl);
            if (requestedItem == null || !itemRl.equals(BuiltInRegistries.ITEM.getKey(requestedItem))) return false;
            CompoundTag tag = decodeNbt(itemNbt);
            if (tag == null) {
                return false;
            }
            ItemStack stack;
            try {
                RegistryOps<Tag> ops = level.registryAccess().createSerializationContext(NbtOps.INSTANCE);
                stack = ItemStack.CODEC.parse(ops, tag).result().orElse(ItemStack.EMPTY);
            } catch (Throwable t) {
                LOG.debug(Guardian.MARKER,
                    "giveOrDrop NBT parse failed at {} {},{},{}; rejecting NBT mutation",
                    worldId, x, y, z, t);
                return false;
            }
            if (stack == null || stack.isEmpty()
                    || !itemRl.equals(BuiltInRegistries.ITEM.getKey(stack.getItem()))) {
                return false;
            }
            // Force the amount from the row — the NBT tag may store 1 but the
            // event captured a stack of N.
            if (amount > 0) stack.setCount(Math.max(1, amount));

            BlockPos pos = new BlockPos(x, y, z);
            BlockEntity be = level.getBlockEntity(pos);
            if (be instanceof Container c && tryInsert(c, stack)) {
                return true;
            }
            ItemEntity drop = new ItemEntity(level, x + 0.5, y + 0.5, z + 0.5, stack);
            drop.setDefaultPickUpDelay();
            return level.addFreshEntity(drop);
        } catch (Throwable t) {
            LOG.warn(Guardian.MARKER, "giveOrDrop (nbt) failed at {} {},{},{}", worldId, x, y, z, t);
            return false;
        }
    }

    @Override
    public boolean tryRespawnEntity(String worldId, int x, int y, int z, String entityType,
                              String targetMeta, byte[] entityNbt) {
        try {
            if (entityNbt == null || entityNbt.length == 0) {
                return tryRespawnEntity(worldId, x, y, z, entityType, targetMeta);
            }
            ServerLevel level = level(worldId);
            if (level == null) return false;
            Identifier entityRl = Identifier.tryParse(entityType);
            if (entityRl == null) return false;
            EntityType<?> requestedType = BuiltInRegistries.ENTITY_TYPE.getValue(entityRl);
            if (requestedType == null || !entityRl.equals(BuiltInRegistries.ENTITY_TYPE.getKey(requestedType))) return false;
            CompoundTag tag = decodeNbt(entityNbt);
            if (tag == null) {
                return false;
            }
            // loadEntityRecursive tolerates modded persistent NBT and returns
            // null on unknown entity id.
            Entity e = EntityType.loadEntityRecursive(tag, level,
                    new net.minecraft.world.entity.EntitySpawnRequest(EntitySpawnReason.LOAD, false), x0 -> {
                x0.snapTo(x + 0.5, y, z + 0.5, x0.getYRot(), x0.getXRot());
                return x0;
            });
            if (e == null || e.getType() != requestedType) {
                // The row's entity id is an integrity boundary; never spawn a
                // decoded entity whose registry type differs from the request.
                return false;
            }
            return level.addFreshEntity(e);
        } catch (Throwable t) {
            LOG.warn(Guardian.MARKER, "respawnEntity (nbt) failed at {} {},{},{}", worldId, x, y, z, t);
            return false;
        }
    }

    /**
     * Decode raw NBT bytes written by {@code NbtIo.write(CompoundTag, DataOutput)}.
     * Returns {@code null} on any decode failure; the checked mutation path then
     * fails closed and never treats the legacy default-state mutation as success.
     */

    private static void loadBlockEntity(BlockEntity be, CompoundTag tag, ServerLevel level) {
        ValueInput input = TagValueInput.create(ProblemReporter.DISCARDING, level.registryAccess(), tag);
        be.loadWithComponents(input);
    }

    private static CompoundTag decodeNbt(byte[] bytes) {
        if (NbtPayload.tooLarge(bytes)) {
            LOG.debug(Guardian.MARKER, "NBT payload {} bytes exceeds cap {}; rejecting decode",
                    bytes.length, NbtPayload.MAX_BYTES);
            return null;
        }
        try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(bytes))) {
            return NbtIo.read(in);
        } catch (Throwable t) {
            LOG.debug(Guardian.MARKER, "NbtIo.read failed ({} bytes): {}", bytes.length, t.toString());
            return null;
        }
    }


    @Override
    public boolean tryRemoveEntity(String worldId, int x, int y, int z, String entityType) {
        try {
            ServerLevel level = level(worldId);
            if (level == null) return false;
            Identifier rl = Identifier.tryParse(entityType);
            if (rl == null) return false;
            EntityType<?> type = BuiltInRegistries.ENTITY_TYPE.getValue(rl);
            if (type == null || !rl.equals(BuiltInRegistries.ENTITY_TYPE.getKey(type))) return false;
            BlockPos pos = new BlockPos(x, y, z);
            AABB box = new AABB(x - 1.0, y - 1.0, z - 1.0, x + 2.0, y + 2.0, z + 2.0);
            for (Entity e : level.getEntitiesOfClass(Entity.class, box,
                    e -> e.getType() == type && e.blockPosition().equals(pos))) {
                e.discard();
                return true;
            }
            return false;
        } catch (Throwable t) {
            LOG.warn(Guardian.MARKER, "removeEntity failed at {} {},{},{}", worldId, x, y, z, t);
            return false;
        }
    }

    // ------------------------------------------------------------------ helpers

    /**
     * One place path for the NBT and NBT-less setBlock overloads.
     * A non-creating read must be null when the target owns no block entity.
     * When the target owns one and no NBT was supplied, the fresh entity is
     * left in place. Failure restores the previous state and returns false.
     */
    private static boolean placeBlock(ServerLevel level, BlockPos pos, BlockState state,
                                      CompoundTag decodedBlockEntityNbt,
                                      BlockState previousState, CompoundTag previousBlockEntityNbt,
                                      String worldId, int x, int y, int z) {
        try {
            return network.vonix.guardian.core.rollback.BlockEntityRestore.place(
                    new network.vonix.guardian.core.rollback.BlockEntityRestore.PlaceOps() {
                        @Override public void setState() {
                            boolean placed = level.setBlock(pos, state, Block.UPDATE_ALL);
                            if (!placed) return;
                        }
                        @Override public boolean stateMatches() {
                            return level.getBlockState(pos).equals(state);
                        }
                        @Override public boolean targetOwnsBlockEntity() {
                            return state.getBlock() instanceof net.minecraft.world.level.block.EntityBlock;
                        }
                        @Override public boolean blockEntityPresent() {
                            return blockEntityCheck(level, pos) != null;
                        }
                        @Override public void removeBlockEntity() {
                            level.removeBlockEntity(pos);
                        }
                        @Override public boolean hasNbt() {
                            return decodedBlockEntityNbt != null;
                        }
                        @Override public boolean applyNbt() {
                            BlockEntity be = blockEntityCheck(level, pos);
                            if (be == null) return false;
                            // Loading NBT into an entity that belongs to another block would restore the
                            // snapshot onto the wrong block; fail closed instead.
                            if (!ownsBlockEntity(level.getBlockState(pos), be, pos)) {
                                LOG.warn(Guardian.MARKER,
                                    "setBlock NBT target entity does not belong to the target block at {} {},{},{}",
                                    worldId, x, y, z);
                                return false;
                            }
                            try {
                                loadBlockEntity(be, decodedBlockEntityNbt, level);
                                be.setChanged();
                                return true;
                            } catch (Throwable t) {
                                LOG.debug(Guardian.MARKER,
                                    "setBlock NBT apply failed at {} {},{},{}; restoring prior block state",
                                    worldId, x, y, z, t);
                                return false;
                            }
                        }
                        @Override public void restorePrevious() {
                            restoreBlockMutation(level, pos, previousState, previousBlockEntityNbt);
                        }
                        @Override public void onStaleClearFailed() {
                            LOG.warn(Guardian.MARKER,
                                "setBlock could not clear stale block entity at {} {},{},{}",
                                worldId, x, y, z);
                        }
                    });
        } catch (Throwable t) {
            LOG.warn(Guardian.MARKER, "setBlock failed at {} {},{},{}", worldId, x, y, z, t);
            if (previousState != null) {
                restoreBlockMutation(level, pos, previousState, previousBlockEntityNbt);
            }
            return false;
        }
    }

    /**
     * True when the block entity at {@code pos} is the type this block state creates.
     * A same-state write can leave a pre-existing entity of another type at the
     * position; loading captured NBT into that entity would restore the snapshot onto
     * the wrong block, so callers fail closed when this returns false.
     */
    private static boolean ownsBlockEntity(BlockState state, BlockEntity be, BlockPos pos) {
        if (be == null || state == null || pos == null) return false;
        if (!(state.getBlock() instanceof net.minecraft.world.level.block.EntityBlock entityBlock)) return false;
        try {
            BlockEntity expected = entityBlock.newBlockEntity(pos, state);
            return expected != null && expected.getType() == be.getType();
        } catch (Throwable t) {
            return false;
        }
    }

    /** Non-creating block-entity read. IMMEDIATE would recreate an empty entity. */
    private static BlockEntity blockEntityCheck(ServerLevel level, BlockPos pos) {
        return level.getChunkAt(pos).getBlockEntity(pos,
                net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK);
    }

    private ServerLevel level(String worldId) {
        if (worldId == null) return null;
        Identifier rl = Identifier.tryParse(worldId);
        if (rl == null) return null;
        ResourceKey<Level> key = ResourceKey.create(Registries.DIMENSION, rl);
        return server.getLevel(key);
    }

    private ItemStack decodeItemStack(String itemId, int amount, byte[] itemNbt) {
        if (itemId == null) return null;
        Identifier itemRl = Identifier.tryParse(itemId);
        if (itemRl == null) return null;
        Item requested = BuiltInRegistries.ITEM.getValue(itemRl);
        if (requested == null || !itemRl.equals(BuiltInRegistries.ITEM.getKey(requested))) return null;
        ItemStack stack;
        if (itemNbt == null || itemNbt.length == 0) {
            stack = new ItemStack(requested, Math.max(1, amount));
        } else {
            CompoundTag tag = decodeNbt(itemNbt);
            if (tag == null) return null;
            try {
                RegistryOps<Tag> ops = server.registryAccess().createSerializationContext(NbtOps.INSTANCE);
                stack = ItemStack.CODEC.parse(ops, tag).result().orElse(ItemStack.EMPTY);
            } catch (Throwable t) {
                return null;
            }
            if (stack == null || stack.isEmpty()
                    || !itemRl.equals(BuiltInRegistries.ITEM.getKey(stack.getItem()))) return null;
            stack.setCount(Math.max(1, amount));
        }
        return stack;
    }

    private static boolean tryRemove(Container c, ItemStack wanted, int amount) {
        int available = 0;
        for (int i = 0; i < c.getContainerSize(); i++) {
            ItemStack cur = c.getItem(i);
            if (!cur.isEmpty() && ItemStack.isSameItemSameComponents(cur, wanted)) {
                available += cur.getCount();
                if (available >= amount) break;
            }
        }
        if (available < amount) return false;
        int remaining = amount;
        for (int i = 0; i < c.getContainerSize() && remaining > 0; i++) {
            ItemStack cur = c.getItem(i);
            if (cur.isEmpty() || !ItemStack.isSameItemSameComponents(cur, wanted)) continue;
            int take = Math.min(remaining, cur.getCount());
            cur.shrink(take);
            remaining -= take;
            if (cur.isEmpty()) c.setItem(i, ItemStack.EMPTY);
        }
        c.setChanged();
        return remaining == 0;
    }

    private static boolean tryAddAtSlot(Container c, int slot, ItemStack stack) {
        if (slot < 0 || slot >= c.getContainerSize() || stack == null || stack.isEmpty()) return false;
        ItemStack current = c.getItem(slot);
        int max = Math.min(stack.getMaxStackSize(), c.getMaxStackSize());
        if (current.isEmpty()) {
            if (stack.getCount() > max) return false;
            ItemStack previous = ItemStack.EMPTY;
            try {
                c.setItem(slot, stack.copy());
                c.setChanged();
                return true;
            } catch (network.vonix.guardian.core.rollback.UncompensatedSlotMutationException e) {
                throw e;
            } catch (Throwable t) {
                restoreExactSlotOrThrow(c, slot, previous, t);
                return false;
            }
        }
        if (!ItemStack.isSameItemSameComponents(current, stack)) return false;
        int space = Math.min(current.getMaxStackSize(), c.getMaxStackSize()) - current.getCount();
        if (space < stack.getCount()) return false;
        ItemStack previous = current.copy();
        try {
            current.grow(stack.getCount());
            c.setChanged();
            return true;
        } catch (network.vonix.guardian.core.rollback.UncompensatedSlotMutationException e) {
            throw e;
        } catch (Throwable t) {
            restoreExactSlotOrThrow(c, slot, previous, t);
            return false;
        }
    }

    private static boolean tryRemoveAtSlot(Container c, int slot, ItemStack wanted, int amount) {
        if (slot < 0 || slot >= c.getContainerSize() || wanted == null || wanted.isEmpty() || amount <= 0) return false;
        ItemStack current = c.getItem(slot);
        if (current.isEmpty() || !ItemStack.isSameItemSameComponents(current, wanted) || current.getCount() < amount) return false;
        ItemStack previous = current.copy();
        try {
            current.shrink(amount);
            if (current.isEmpty()) c.setItem(slot, ItemStack.EMPTY);
            c.setChanged();
            return true;
        } catch (network.vonix.guardian.core.rollback.UncompensatedSlotMutationException e) {
            throw e;
        } catch (Throwable t) {
            restoreExactSlotOrThrow(c, slot, previous, t);
            return false;
        }
    }


    private static void restoreExactSlotOrThrow(Container c, int slot, ItemStack previous, Throwable mutateFailure) {
        Throwable restoreFailure = null;
        boolean restored = false;
        try {
            c.setItem(slot, previous);
            c.setChanged();
            ItemStack now = c.getItem(slot);
            restored = exactSlotStacksMatch(now, previous);
        } catch (Throwable t) {
            restoreFailure = t;
        }
        if (!restored) {
            LOG.error(Guardian.MARKER, "exact-slot compensation failed at slot={}; world may remain mutated", slot, mutateFailure);
            throw new network.vonix.guardian.core.rollback.UncompensatedSlotMutationException(slot, mutateFailure, restoreFailure);
        }
    }

    private static boolean exactSlotStacksMatch(ItemStack a, ItemStack b) {
        if (a == b) return true;
        if (a == null || b == null) return false;
        if (a.isEmpty() && b.isEmpty()) return true;
        if (a.isEmpty() || b.isEmpty()) return false;
        if (a.getCount() != b.getCount()) return false;
        return ItemStack.isSameItemSameComponents(a, b);
    }

    private static boolean tryInsertComplete(Container c, ItemStack stack) {
        int capacity = 0;
        for (int i = 0; i < c.getContainerSize(); i++) {
            ItemStack cur = c.getItem(i);
            if (cur.isEmpty()) {
                capacity += Math.min(stack.getMaxStackSize(), c.getMaxStackSize());
            } else if (ItemStack.isSameItemSameComponents(cur, stack)) {
                capacity += Math.max(0, Math.min(cur.getMaxStackSize(), c.getMaxStackSize()) - cur.getCount());
            }
            if (capacity >= stack.getCount()) return tryInsert(c, stack);
        }
        return false;
    }

    private static boolean tryInsert(Container c, ItemStack stack) {
        int size = c.getContainerSize();
        long capacity = 0L;
        for (int i = 0; i < size && capacity < stack.getCount(); i++) {
            ItemStack cur = c.getItem(i);
            if (cur.isEmpty()) {
                capacity += Math.min(stack.getMaxStackSize(), c.getMaxStackSize());
            } else if (ItemStack.isSameItemSameComponents(cur, stack)) {
                capacity += Math.max(0, Math.min(cur.getMaxStackSize(), c.getMaxStackSize()) - cur.getCount());
            }
        }
        // Preflight capacity so a failed insert cannot be followed by a duplicate drop.
        if (capacity < stack.getCount()) return false;
        // 1) merge into matching stacks
        for (int i = 0; i < size && !stack.isEmpty(); i++) {
            ItemStack cur = c.getItem(i);
            if (!cur.isEmpty() && ItemStack.isSameItemSameComponents(cur, stack)) {
                int space = Math.min(cur.getMaxStackSize(), c.getMaxStackSize()) - cur.getCount();
                if (space <= 0) continue;
                int move = Math.min(space, stack.getCount());
                cur.grow(move);
                stack.shrink(move);
            }
        }
        // 2) fill empty slots
        for (int i = 0; i < size && !stack.isEmpty(); i++) {
            if (c.getItem(i).isEmpty()) {
                int move = Math.min(stack.getCount(),
                    Math.min(stack.getMaxStackSize(), c.getMaxStackSize()));
                ItemStack placed = stack.copy();
                placed.setCount(move);
                c.setItem(i, placed);
                stack.shrink(move);
            }
        }
        if (stack.isEmpty()) {
            c.setChanged();
            return true;
        }
        return false;
    }

    /**
     * Best-effort apply of {@code targetMeta} block-state properties. Accepts
     * either a bare {@code key=value,key=value} list or a JSON object of
     * {@code {"key":"value"}} pairs; unrecognised properties/values are
     * silently skipped so a mismatched meta blob never blocks rollback.
     */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static BlockState applyMeta(BlockState base, String meta) {
        if (meta == null || meta.isEmpty()) return base;
        String body = meta.trim();
        if (body.startsWith("{")) {
            // Strip outer braces; tolerate quoted or bare tokens.
            body = body.substring(1, body.endsWith("}") ? body.length() - 1 : body.length());
        }
        BlockState state = base;
        for (String kv : body.split(",")) {
            int eq = kv.indexOf('=');
            if (eq <= 0 || eq >= kv.length() - 1) {
                int colon = kv.indexOf(':');
                if (colon <= 0 || colon >= kv.length() - 1) continue;
                eq = colon;
            }
            String key = unquote(kv.substring(0, eq).trim());
            String val = unquote(kv.substring(eq + 1).trim());
            if (key.isEmpty() || val.isEmpty()) continue;
            net.minecraft.world.level.block.state.properties.Property property =
                    state.getBlock().getStateDefinition().getProperty(key);
            if (property == null) continue;
            java.util.Optional value = property.getValue(val);
            if (value.isEmpty()) continue;
            try {
                state = state.setValue((net.minecraft.world.level.block.state.properties.Property) property,
                        (Comparable) value.get());
            } catch (Throwable ignored) {
                // property applied to wrong block after registry drift — skip
            }
        }
        return state;
    }

    private static String unquote(String s) {
        if (s.length() >= 2 && ((s.charAt(0) == '"' && s.charAt(s.length() - 1) == '"')
                || (s.charAt(0) == '\'' && s.charAt(s.length() - 1) == '\''))) {
            return s.substring(1, s.length() - 1);
        }
        return s;
    }

}

